113	/** Keeps the role each sheet gives a user name: clerk (any name with none), steward or viewer; and the
114	 *  delegations of the steward role, under which a user acts as a steward while the sheet's today is in range. */
115	@Service
116	public class RoleService {
117	
118	    private final SheetRoleRepository roles;
119	    private final DelegationRepository delegations;
120	    private final SheetRepository sheets;
121	    private final Audit audit;
122	
123	    public RoleService(SheetRoleRepository roles, DelegationRepository delegations, SheetRepository sheets,
124	            Audit audit) {
125	        this.roles = roles;
126	        this.delegations = delegations;
127	        this.sheets = sheets;
128	        this.audit = audit;
129	    }
130	
131	    @Transactional(readOnly = true)
132	    public List<SheetRole> list(String sheetId) {
133	        requireSheet(sheetId);
134	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
135	    }
136	
137	    /** Give a user name a role on the sheet, replacing the one it had. */
138	    @Transactional
139	    public SheetRole set(String sheetId, String user, String name, String role) {
140	        requireSheet(sheetId);
141	        SheetRole row = roles.findBySheetIdAndUserName(sheetId, name).orElse(null);
142	        if (row == null) {
143	            try {
144	                row = roles.saveAndFlush(new SheetRole(sheetId, name, role));
145	            } catch (DataIntegrityViolationException e) {
146	                throw new RoleConflictException();
147	            }
148	        } else {
149	            row.setRole(role);
150	            row = roles.saveAndFlush(row);
151	        }
152	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role);
153	        return row;
154	    }
155	
156	    @Transactional(readOnly = true)
157	    public List<Delegation> delegations(String sheetId) {
158	        requireSheet(sheetId);
159	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
160	    }
161	
162	    /** A steward delegates the steward role to a user name from a date (none: the sheet's today) to a date
163	     *  (none: the from-date), inclusive. Anyone but a steward is refused, as is a to-date before the from-date. */
164	    @Transactional
165	    public Delegation delegate(String sheetId, String user, String name, LocalDate from, LocalDate to) {
166	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
167	        if (!hasStewardRole(sheetId, user)) {
168	            throw new DelegationRefusedException("Only a steward may delegate the steward role.");
169	        }
170	        LocalDate start = from == null ? sheet.getToday() : from;
171	        LocalDate end = to == null ? start : to;
172	        if (end.isBefore(start)) {
173	            throw new DelegationRefusedException("The to-date may not be before the from-date.");
174	        }
175	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, user, name, start, end));
176	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + name
177	                + " from=" + start + " to=" + end);
178	        return saved;
179	    }
180	
181	    /** Whether the sheet makes the user name a steward: given the role, or delegated it for the sheet's today. */
182	    @Transactional(readOnly = true)
183	    public boolean isSteward(String sheetId, String name) {
184	        return hasStewardRole(sheetId, name) || delegatorOf(sheetId, name) != null;
185	    }
186	
187	    /** The steward the user acts for: the one who delegated them the steward role for the sheet's today, when
188	     *  they are not a steward themselves; none otherwise. */
189	    @Transactional(readOnly = true)
190	    public String actingFor(String sheetId, String name) {
191	        return hasStewardRole(sheetId, name) ? null : delegatorOf(sheetId, name);
192	    }
193	
194	    private boolean hasStewardRole(String sheetId, String name) {
195	        return roles.findBySheetIdAndUserName(sheetId, name)
196	                .map(r -> SheetRole.STEWARD.equals(r.getRole()))
197	                .orElse(false);
198	    }
199	
200	    /** The latest delegator of the steward role to the user covering the sheet's today; none when none does. */
201	    private String delegatorOf(String sheetId, String name) {
202	        List<Delegation> given = delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, name);
203	        if (given.isEmpty()) {
204	            return null;
205	        }
206	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
207	        if (today == null) {
208	            return null;
209	        }
210	        return given.stream().filter(d -> d.covers(today)).map(Delegation::getDelegator).findFirst().orElse(null);
211	    }
212	
213	    /** Whether the sheet makes the user name a viewer, who sees the sheet and changes nothing; a user delegated
214	     *  the steward role acts as a steward. */
215	    @Transactional(readOnly = true)
216	    public boolean isViewer(String sheetId, String name) {
217	        if (delegatorOf(sheetId, name) != null) {
218	            return false;
219	        }
220	        return roles.findBySheetIdAndUserName(sheetId, name)
221	                .map(r -> SheetRole.VIEWER.equals(r.getRole()))
222	                .orElse(false);
223	    }
224	
225	    /** Refuse any change by a viewer. */
226	    public void requireNotViewer(String sheetId, String name) {
227	        if (isViewer(sheetId, name)) {
228	            throw new ActionNotAllowedException("change anything");
229	        }
230	    }
231	
232	    /** Whether the user's role on the sheet may take an action, by the sheet's permission matrix (an action
233	     *  with no roles set keeps the standing rule). */
234	    @Transactional(readOnly = true)
235	    public boolean allows(String sheetId, String name, String action) {
236	        if (isViewer(sheetId, name)) {
237	            return false;
238	        }
239	        String role = isSteward(sheetId, name) ? SheetRole.STEWARD : SheetRole.CLERK;
240	        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).allows(action, role);
241	    }
242	
243	    /** Refuse an action the user's role on the sheet may not take. */
244	    public void require(String sheetId, String name, String action) {
245	        if (!allows(sheetId, name, action)) {
246	            throw new ActionNotAllowedException(action);
247	        }
248	    }
249	
250	    private void requireSheet(String sheetId) {
251	        if (!sheets.existsById(sheetId)) {
252	            throw new SheetNotFoundException();
253	        }
254	    }
255	}
