514	        String typed = permissions.get(action);
515	        List<String> allowed = typed == null ? STANDING_PERMISSIONS.getOrDefault(action, List.of())
516	                : Arrays.stream(typed.split(",")).map(String::trim).toList();
517	        return allowed.contains(role);
