544	    /** Whether a claim opened now is numbered within its period: the setting is a date and today is on or
545	     *  after it. */
546	    public boolean numbersByPeriod() {
547	        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
548	    }
549	
550	    /** How a claim dated on a date rounds its figures: half up before the policy date (the sheet's today
551	     *  when it has none), half to even on or after it. */
552	    public RoundingMode rounding(LocalDate date) {
553	        LocalDate policy = policyDate == null ? today : policyDate;
554	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
555	    }
556	
557	    /** The late charge on an overdue claim's figure: for each full 30 days past its due-by on the sheet's
558	     *  today, the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of the
559	     *  figure, rounded to cents as its date rounds, the charges added up (a boundary at 0.00 adds nothing);
560	     *  0.00 for no figure (n/a). Only an OPEN or PENDING claim is overdue, so the caller asks only for those. */
561	    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date) {
562	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
563	        if (figure == null) {
564	            return charge;
565	        }
566	        long boundaries = ChronoUnit.DAYS.between(dueBy, today) / 30;
567	        RoundingMode rounding = rounding(date);
568	        for (long k = 1; k <= boundaries; k++) {
569	            charge = charge.add(figure.multiply(latePctOn(dueBy.plusDays(30 * k))).movePointLeft(2)
570	                    .setScale(2, rounding));
571	        }
572	        return charge;
573	    }
574	
575	    /** A live due of a claim dated on a date as it counts: at least the floor in force then; none (n/a)
576	     *  stays none. */
577	    public BigDecimal floored(BigDecimal due, LocalDate date) {
578	        return due == null ? null : due.max(floorOn(date));
579	    }
580	
581	    /** Give out the sheet's next claim number. */
582	    public String nextClaimNumber() {
583	        return String.valueOf(++lastClaimNumber);
584	    }
585	}
586	package net.officefloor.hq.app.sheet;
587	
588	import java.math.BigDecimal;
589	import java.time.Instant;
590	import java.time.LocalDate;
591	import net.officefloor.hq.app.Audit;
592	import net.officefloor.hq.app.period.Period;
593	import net.officefloor.hq.app.period.PeriodRepository;
