595	import net.officefloor.hq.app.rollup.Rollup;
596	import org.springframework.dao.DataIntegrityViolationException;
597	import org.springframework.stereotype.Service;
598	import org.springframework.transaction.annotation.Transactional;
599	
600	/** Loads sheets by id; a sheet never loaded before is started empty, its today the real date. */
601	@Service
602	public class SheetService {
603	
604	    private final SheetRepository sheets;
605	    private final ClaimSequenceRepository sequences;
606	    private final PeriodRepository periods;
607	    private final PeriodService periodService;
608	    private final Rollup rollup;
609	    private final Audit audit;
610	
611	    public SheetService(SheetRepository sheets, ClaimSequenceRepository sequences, PeriodRepository periods,
612	            PeriodService periodService, Rollup rollup, Audit audit) {
613	        this.sheets = sheets;
614	        this.sequences = sequences;
615	        this.periods = periods;
616	        this.periodService = periodService;
617	        this.rollup = rollup;
618	        this.audit = audit;
619	    }
620	
621	    @Transactional
622	    public Sheet load(String id, String user) {
623	        return sheets.findById(id).orElseGet(() -> {
624	            try {
625	                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
626	            } catch (DataIntegrityViolationException e) {
627	                // Another user started the same sheet at the same moment.
628	                return sheets.findById(id).orElseThrow(() -> e);
629	            }
630	        });
631	    }
632	
633	    /** The sheet's today. Every date decision and default date in the sheet goes through this. */
634	    @Transactional(readOnly = true)
635	    public LocalDate today(String id) {
636	        return sheets.findById(id).map(Sheet::getToday).orElseThrow(SheetNotFoundException::new);
637	    }
638	
639	    /** Change the sheet's today, closing the periods past their grace days and recording the figures it
640	     *  moves. */
641	    @Transactional
642	    public Sheet setToday(String id, String user, LocalDate today) {
643	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
644	        Rollup.Snapshot before = rollup.take(id);
645	        sheet.setToday(today);
646	        sheets.saveAndFlush(sheet);
647	        periodService.closeOverdue(id, user, today, sheet.getGraceDays());
648	        rollup.recordChanges(id, user, before);
649	        return sheet;
650	    }
651	
652	    /** Record the sheet's clerk limit from a date (none: the sheet's today): the largest due a clerk may
653	     *  settle; none for no limit. */
654	    @Transactional
655	    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
656	        return setDated(id, user, Sheet.CLERK_LIMIT, limit == null ? null : limit.setScale(2).toPlainString(), from,
657	                false);
658	    }
659	
660	    /** Record the sheet's floor from a date (none: the sheet's today): the least a claim's live due can be,
661	     *  recording the figures it moves. */
662	    @Transactional
663	    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
664	        return setDated(id, user, Sheet.FLOOR, floor.setScale(2).toPlainString(), from, true);
665	    }
666	
667	    /** Record the sheet's cap from a date (none: the sheet's today): the most a person's due-total can be
668	     *  (none: no cap), recording the figures it moves. */
669	    @Transactional
670	    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
671	        return setDated(id, user, Sheet.CAP, cap == null ? null : cap.setScale(2).toPlainString(), from, true);
672	    }
673	
674	    /** Record the sheet's proof threshold from a date (none: the sheet's today): a claim dated then whose due
675	     *  is above it needs a proof to be settled or approved; none for no threshold. */
676	    @Transactional
677	    public Sheet setProofThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
678	        return setDated(id, user, Sheet.PROOF_THRESHOLD, threshold == null ? null : threshold.setScale(2).toPlainString(),
679	                from, false);
680	    }
681	
682	    /** Record the sheet's terms from a date (none: the sheet's today): the number of days after a claim's
683	     *  date it is due by, for a claim added later dated then whose grade has no terms of its own. A claim
684	     *  already added keeps its due-by. */
685	    @Transactional
686	    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
687	        return setDated(id, user, Sheet.TERMS, Integer.toString(terms), from, false);
688	    }
689	
690	    /** Record a grade's own terms from a date (none: the sheet's today; no terms: it uses the sheet's
691	     *  terms), for a claim added later. A claim already added keeps its due-by. */
692	    @Transactional
693	    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
694	        return setDated(id, user, Sheet.TERMS + "-" + grade, terms == null ? null : terms.toString(), from, false);
695	    }
696	
697	    /** Record the sheet's late percent from a date (none: the sheet's today), recording the figures it
698	     *  moves. */
699	    @Transactional
700	    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
701	        return setDated(id, user, Sheet.LATE_PCT, latePct.setScale(2).toPlainString(), from, true);
702	    }
703	
704	    /** Record a dated setting's value (none: blank) from a date, the sheet's today when none is given,
705	     *  replacing one already from that date; when it can move figures, record those that moved. */
706	    private Sheet setDated(String id, String user, String key, String value, LocalDate from, boolean movesFigures) {
707	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
708	        Rollup.Snapshot before = movesFigures ? rollup.take(id) : null;
709	        sheet.setSetting(key, from == null ? sheet.getToday() : from, value);
710	        sheets.saveAndFlush(sheet);
711	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value="
712	                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
713	        if (movesFigures) {
714	            rollup.recordChanges(id, user, before);
715	        }
716	        return sheet;
717	    }
718	
719	    /** Change the sheet's policy date (none: the sheet's today), recording the figures it moves. */
720	    @Transactional
721	    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
722	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
723	        Rollup.Snapshot before = rollup.take(id);
724	        sheet.setPolicyDate(policyDate);
725	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
726	                + (policyDate == null ? "" : policyDate.toString()));
727	        rollup.recordChanges(id, user, before);
728	        return sheet;
729	    }
730	
731	    /** Set the roles that may take an action (open, settle, void, reassign, close or reopen), comma
732	     *  separated; blank keeps the standing rule. Not dated. */
733	    @Transactional
734	    public Sheet setPermission(String id, String user, String action, String roles) {
735	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
736	        String value = roles == null ? "" : roles.trim();
737	        sheet.setPermission(action, value);
738	        sheets.saveAndFlush(sheet);
739	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=perm-" + action + " value=" + value);
740	        return sheet;
741	    }
742	
743	    /** Change the sheet's grace days (none: off). Not dated. */
744	    @Transactional
745	    public Sheet setGraceDays(String id, String user, Integer graceDays) {
746	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
747	        sheet.setGraceDays(graceDays);
748	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=grace-days value="
749	                + (graceDays == null ? "" : graceDays.toString()));
750	        return sheet;
751	    }
752	
753	    /** Change the sheet's period numbering from-date (none: off). */
754	    @Transactional
755	    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
756	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
757	        sheet.setPeriodNumberingFrom(from);
758	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
759	                + (from == null ? "" : from.toString()));
760	        return sheet;
761	    }
762	
763	    /** The next number for a claim dated on a date: while the sheet numbers by period, the next in the
764	     *  sequence of the period containing the date (<period name>-1, -2, ...), or of no period (X-1, ...);
765	     *  otherwise the sheet-wide one (1, 2, ...). None is ever given twice. */
766	    @Transactional
767	    public String nextClaimNumber(String id, LocalDate date) {
768	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
769	        if (!sheet.numbersByPeriod()) {
770	            return sheet.nextClaimNumber();
771	        }
772	        String prefix = periods.findBySheetIdOrderByFromDateAsc(id).stream()
773	                .filter(p -> p.contains(date)).findFirst().map(Period::getName).orElse("X");
774	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(id, prefix)
775	                .orElseGet(() -> new ClaimSequence(id, prefix));
776	        String number = sequence.nextClaimNumber();
777	        sequences.save(sequence);
778	        return number;
779	    }
780	}
